import test from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {readFileSync,readdirSync,mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {build} from 'esbuild';
const compiled=await build({entryPoints:['lib/server/service.ts'],bundle:true,format:'esm',platform:'node',write:false});
const {Service}=await import('data:text/javascript;base64,'+Buffer.from(compiled.outputFiles[0].text).toString('base64'));
class D1 {
 constructor(path=':memory:'){this.sql=new DatabaseSync(path);this.sql.exec('PRAGMA foreign_keys=ON');}
 prepare(sql){const db=this;return {args:[],bind(...args){this.args=args;return this},async all(){const stmt=db.sql.prepare(sql);const results=stmt.all(...this.args);return {results,success:true,meta:{changes:Number(db.sql.prepare('SELECT changes() n').get().n)}}},async first(){return db.sql.prepare(sql).get(...this.args)??null},async run(){const r=db.sql.prepare(sql).run(...this.args);return {results:[],success:true,meta:{changes:Number(r.changes)}}},_sql:sql};}
 async batch(stmts){this.sql.exec('BEGIN');try{const results=[];for(const s of stmts){if(/\bRETURNING\b/i.test(s._sql))results.push(await s.all());else results.push(await s.run());}this.sql.exec('COMMIT');return results}catch(e){this.sql.exec('ROLLBACK');throw e}}
 migrate(){for(const f of readdirSync('drizzle').filter(f=>f.endsWith('.sql')).sort())this.sql.exec(readFileSync(join('drizzle',f),'utf8'));}
 close(){this.sql.close()}
}
const alice={id:'alice',name:'Alice Owner',email:'alice@example.com'},bob={id:'bob',name:'Bob Owner',email:'bob@example.com'},eve={id:'eve',name:'Eve Viewer',email:'eve@example.com'};
async function setup(){const db=new D1();db.migrate();const a=new Service(db,alice),b=new Service(db,bob);const oa=(await a.createOrganization({name:'Alpha'})).id,ob=(await b.createOrganization({name:'Beta'})).id;const ca=(await a.directory(oa,'companies',{name:'Alpha customer'})).id,cb=(await b.directory(ob,'companies',{name:'Beta customer'})).id;const ba=(await a.workspace(oa)).boards[0].id,bb=(await b.workspace(ob)).boards[0].id;return {db,a,b,oa,ob,ca,cb,ba,bb}}
const failStatus=status=>e=>e.status===status;
test('missing stable identity cannot create a service',()=>{assert.throws(()=>new Service({},null),failStatus(401));assert.throws(()=>new Service({},{email:'a@x.com',name:'a'}),failStatus(401))});
test('organization membership gates all resource entrypoints',async()=>{const {db,a,b,oa,ob,cb,bb}=await setup();try{await assert.rejects(a.workspace(ob),failStatus(403));await assert.rejects(a.listTickets(ob,new URL('https://test/tickets')),failStatus(403));await assert.rejects(a.ticket(ob,1001),failStatus(403));await assert.rejects(a.createTicket(ob,{title:'Intrusion',companyId:cb,boardId:bb}),failStatus(403));await assert.rejects(a.directory(ob,'companies',{name:'Intrusion'}),failStatus(403));await assert.rejects(a.team(ob),failStatus(403));await assert.rejects(a.audit(ob,new URL('https://test')),failStatus(403));await assert.rejects(a.organization(ob,{name:'Changed'}),failStatus(403));await assert.rejects(a.invite(ob,{email:'x@example.com',role:'Viewer'}),failStatus(403));assert.equal((await b.workspace(ob)).organization.name,'Beta')}finally{db.close()}});
test('company, contact, board, and assignee references must share a tenant',async()=>{const {db,a,oa,ob,ca,cb,ba,bb,b}=await setup();try{const foreignContact=(await b.directory(ob,'contacts',{name:'Private person',companyId:cb})).id;for(const extra of [{companyId:cb},{boardId:bb},{contactId:foreignContact},{assigneeId:bob.id}])await assert.rejects(a.createTicket(oa,{title:'Test',companyId:ca,boardId:ba,...extra}),failStatus(400));assert.equal((await a.listTickets(oa,new URL('https://test/?view=all'))).total,0);assert.throws(()=>db.sql.prepare('INSERT INTO contacts(id,org_id,company_id,name) VALUES(?,?,?,?)').run('bypass',oa,cb,'Nope'),/FOREIGN KEY/)}finally{db.close()}});
test('ticket lifecycle persists assignments, notes, and actor-attributed audit',async()=>{const {db,a,oa,ca,ba}=await setup();try{const contact=(await a.directory(oa,'contacts',{name:'Pat',companyId:ca,email:'pat@example.com'})).id;let t=await a.createTicket(oa,{title:'VPN fails',description:'Remote staff affected',companyId:ca,contactId:contact,boardId:ba});assert.equal(t.id,1001);assert.equal(t.contact,'Pat');t=await a.updateTicket(oa,String(t.id),{status:'In Progress',assigneeId:alice.id,priority:'Critical',version:t.version});assert.equal(t.assignee,'Alice Owner');t=await a.addNote(oa,String(t.id),{body:'Checked gateway logs.',version:t.version});assert.equal(t.notes[0].author,'Alice Owner');assert.equal(t.activity[0].author,'Alice Owner');assert.equal(t.version,3);t=await a.updateTicket(oa,String(t.id),{status:'Resolved',version:t.version});assert.equal(t.closed,1);const list=await a.listTickets(oa,new URL('https://test/?view=open'));assert.equal(list.total,0);assert.equal(list.summary.open,0);assert.equal((await a.listTickets(oa,new URL('https://test/?view=all&q=gateway'))).total,1)}finally{db.close()}});
test('stale writes and notes do not overwrite records or append audit',async()=>{const {db,a,oa,ca,ba}=await setup();try{const t=await a.createTicket(oa,{title:'Issue',companyId:ca,boardId:ba});await a.updateTicket(oa,String(t.id),{priority:'High',version:1});const before=await a.ticket(oa,t.id);await assert.rejects(a.updateTicket(oa,String(t.id),{priority:'Low',version:1}),failStatus(409));await assert.rejects(a.addNote(oa,String(t.id),{body:'Stale note',version:1}),failStatus(409));const after=await a.ticket(oa,t.id);assert.equal(after.priority,'High');assert.equal(after.notes.length,0);assert.equal(after.activity.length,before.activity.length);assert.equal(after.version,2)}finally{db.close()}});
test('same ticket number in two organizations never shares notes or details',async()=>{const {db,a,b,oa,ob,ca,cb,ba,bb}=await setup();try{const ta=await a.createTicket(oa,{title:'Alpha secret',companyId:ca,boardId:ba}),tb=await b.createTicket(ob,{title:'Beta secret',companyId:cb,boardId:bb});assert.equal(ta.id,tb.id);await b.addNote(ob,String(tb.id),{body:'Beta confidential',version:tb.version});assert.equal((await a.ticket(oa,ta.id)).notes.length,0);assert.equal((await a.listTickets(oa,new URL('https://test/?view=all&q=Beta'))).total,0);await assert.rejects(a.addNote(ob,String(tb.id),{body:'No',version:2}),failStatus(403))}finally{db.close()}});
test('invitations require matching identity, acceptance, and enforce role limits',async()=>{const {db,a,oa,ca,ba}=await setup();try{const viewer=new Service(db,eve);await viewer.account();await a.invite(oa,{email:eve.email.toUpperCase(),role:'Viewer'});const invitation=(await viewer.account()).invitations[0];await assert.rejects(viewer.workspace(oa),failStatus(403));const stranger=new Service(db,{id:'stranger',email:'stranger@example.com',name:'Stranger'});await stranger.account();await assert.rejects(stranger.acceptInvitation({invitationId:invitation.id}),failStatus(404));await viewer.acceptInvitation({invitationId:invitation.id});assert.equal((await viewer.workspace(oa)).organization.role,'Viewer');await assert.rejects(viewer.createTicket(oa,{title:'Not allowed',companyId:ca,boardId:ba}),failStatus(403));await assert.rejects(viewer.directory(oa,'companies',{name:'No'}),failStatus(403));await assert.rejects(viewer.team(oa),failStatus(403));await a.role(oa,eve.id,{role:'Engineer'});assert.equal((await viewer.createTicket(oa,{title:'Allowed now',companyId:ca,boardId:ba})).title,'Allowed now');await assert.rejects(viewer.directory(oa,'boards',{name:'No',statuses:[]}),failStatus(403));await assert.rejects(a.role(oa,alice.id,{role:'Viewer'}),failStatus(403))}finally{db.close()}});
test('revoked and expired invitations do not grant membership',async()=>{const {db,a,oa}=await setup();try{const v=new Service(db,eve);await v.account();await a.invite(oa,{email:eve.email,role:'Engineer'});let i=(await v.account()).invitations[0];await a.revokeInvite(oa,i.id);await assert.rejects(v.acceptInvitation({invitationId:i.id}),failStatus(404));await a.invite(oa,{email:eve.email,role:'Engineer'});i=(await v.account()).invitations[0];db.sql.prepare('UPDATE invitations SET expires=? WHERE id=?').run('2000-01-01T00:00:00.000Z',i.id);await assert.rejects(v.acceptInvitation({invitationId:i.id}),failStatus(404));await assert.rejects(v.workspace(oa),failStatus(403))}finally{db.close()}});
test('used board statuses retain their meaning; directory writes use versions',async()=>{const {db,a,oa,ca,ba}=await setup();try{await a.createTicket(oa,{title:'Status test',companyId:ca,boardId:ba});const w=await a.workspace(oa),board=w.boards.find(b=>b.id===ba);await assert.rejects(a.directory(oa,'boards',{name:board.name,description:'',statuses:board.statuses.filter(s=>s.name!=='New'),version:board.version},ba),failStatus(409));await a.directory(oa,'boards',{name:board.name,description:'Custom',statuses:[...board.statuses,{name:'Pending approval',closed:false}],version:board.version},ba);const c=w.companies[0];await a.directory(oa,'companies',{name:'Renamed',version:c.version},c.id);await assert.rejects(a.directory(oa,'companies',{name:'Stale',version:c.version},c.id),failStatus(409));assert.equal((await a.listTickets(oa,new URL('https://test/?view=all'))).tickets[0].company,'Renamed')}finally{db.close()}});
test('sample option seeds 54 tickets, directory records, pagination, and filters',async()=>{const db=new D1();db.migrate();try{const a=new Service(db,alice),org=(await a.createOrganization({name:'Sample',sample:true})).id,w=await a.workspace(org);assert.equal(w.companies.length,10);assert.equal(w.contacts.length,25);let p=await a.listTickets(org,new URL('https://test/?view=all'));assert.equal(p.total,54);assert.equal(p.tickets.length,12);const p2=await a.listTickets(org,new URL('https://test/?view=all&page=1'));assert.ok(!p2.tickets.some(t=>p.tickets.some(x=>x.id===t.id)));p=await a.listTickets(org,new URL('https://test/?view=all&q=1048'));assert.equal(p.total,1);p=await a.listTickets(org,new URL('https://test/?view=mine'));assert.ok(p.tickets.every(t=>t.assigneeId===alice.id&&!t.closed));p=await a.listTickets(org,new URL('https://test/?view=all&priority=Critical&sort=priority'));assert.ok(p.tickets.every(t=>t.priority==='Critical'));const w2=(await a.createOrganization({name:'Empty'})).id;assert.equal((await a.listTickets(w2,new URL('https://test/?view=all'))).total,0)}finally{db.close()}});
test('unknown fields, oversized text, and invalid status are rejected',async()=>{const {db,a,oa,ca,ba}=await setup();try{await assert.rejects(a.createTicket(oa,{title:'No',companyId:ca,boardId:ba,orgId:'foreign'}));await assert.rejects(a.createTicket(oa,{title:'x'.repeat(181),companyId:ca,boardId:ba}));await assert.rejects(a.createTicket(oa,{title:'No',companyId:ca,boardId:ba,status:'Made up'}),failStatus(400));await assert.rejects(a.listTickets(oa,new URL('https://test/?page=-1')))}finally{db.close()}});
test('database state survives process-style database reconnection',async()=>{const dir=mkdtempSync(join(tmpdir(),'queuepilot-test-')),path=join(dir,'db.sqlite');let db=new D1(path);try{db.migrate();let a=new Service(db,alice);const org=(await a.createOrganization({name:'Persistent'})).id;const c=(await a.directory(org,'companies',{name:'Saved customer'})).id,b=(await a.workspace(org)).boards[0].id;await a.createTicket(org,{title:'Saved ticket',companyId:c,boardId:b});db.close();db=new D1(path);a=new Service(db,alice);assert.equal((await a.listTickets(org,new URL('https://test/?view=all'))).tickets[0].title,'Saved ticket')}finally{db.close();rmSync(dir,{recursive:true,force:true})}});
const httpBundle=await build({stdin:{contents:"export * as account from './app/api/account/route.ts'; export * as workspace from './app/api/workspace/[...path]/route.ts';",resolveDir:process.cwd(),sourcefile:'http-test-entry.ts'},bundle:true,format:'esm',platform:'node',write:false,plugins:[{name:'test-runtime',setup(b){b.onResolve({filter:/^(cloudflare:workers|next\/headers)$/},args=>({path:args.path,namespace:'test-runtime'}));b.onLoad({filter:/.*/,namespace:'test-runtime'},args=>({contents:args.path==='cloudflare:workers'?'export const env=globalThis.__qpTestEnv;':'export async function headers(){return globalThis.__qpTestHeaders};export async function cookies(){return {getAll:()=>[],set(){}}}',loader:'js'}));}}]});
globalThis.__qpTestEnv={};globalThis.__qpTestHeaders=new Headers();
const http=await import('data:text/javascript;base64,'+Buffer.from(httpBundle.outputFiles[0].text).toString('base64'));
test('HTTP routes reject anonymous identity, cross-site mutations and untrusted tenant fields',async()=>{const {db,a,oa,ob,ca,ba}=await setup();try{globalThis.__qpTestEnv.DB=db;globalThis.__qpTestHeaders=new Headers();let r=await http.account.GET();assert.equal(r.status,401);globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-email':alice.email});r=await http.account.GET();assert.equal(r.status,200);const fallbackAccount=await r.json();assert.match(fallbackAccount.user.id,/^sites-email:[a-f0-9]{64}$/);assert.equal(fallbackAccount.organizations.length,0);globalThis.__qpTestHeaders.set('oai-authenticated-user-id',alice.id);r=await http.account.GET();assert.equal(r.status,200);assert.equal(r.headers.get('cache-control'),'private, no-store');const ctx={params:Promise.resolve({path:[oa,'tickets']})},data={title:'HTTP ticket',companyId:ca,boardId:ba};const request=(extra={},payload=data)=>new Request('https://queuepilot.test/api/workspace/'+oa+'/tickets',{method:'POST',headers:{'Content-Type':'application/json',...extra},body:JSON.stringify(payload)});r=await http.workspace.POST(request(),ctx);assert.equal(r.status,403);r=await http.workspace.POST(request({'X-QueuePilot-Request':'1',Origin:'https://attacker.test'}),ctx);assert.equal(r.status,403);r=await http.workspace.POST(request({'X-QueuePilot-Request':'1','Sec-Fetch-Site':'cross-site'}),ctx);assert.equal(r.status,403);r=await http.workspace.POST(request({'X-QueuePilot-Request':'1'}, {...data,orgId:ob}),ctx);assert.equal(r.status,400);r=await http.workspace.POST(request({'X-QueuePilot-Request':'1'}, {...data,description:'x'.repeat(40000)}),ctx);assert.equal(r.status,413);r=await http.workspace.POST(request({'X-QueuePilot-Request':'1',Origin:'https://queuepilot.test'}),ctx);assert.equal(r.status,200);assert.equal((await r.json()).title,'HTTP ticket');r=await http.workspace.GET(new Request('https://queuepilot.test/api/workspace/'+ob),{params:Promise.resolve({path:[ob]})});assert.equal(r.status,403);assert.ok(!(await r.text()).includes('Beta customer'));}finally{db.close();globalThis.__qpTestEnv.DB=undefined;globalThis.__qpTestHeaders=new Headers()}});

test('email-only dispatcher identity can onboard, reload and access only its own workspace',async()=>{
 const db=new D1();db.migrate();
 try{
  globalThis.__qpTestEnv.DB=db;
  globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-email':' Legacy@Example.com ','oai-authenticated-user-full-name':'Legacy%20Owner','oai-authenticated-user-full-name-encoding':'percent-encoded-utf-8'});
  let response=await http.account.GET();assert.equal(response.status,200);const first=await response.json();assert.equal(first.user.name,'Legacy Owner');assert.equal(first.user.email,'legacy@example.com');
  response=await http.account.POST(new Request('https://queuepilot.test/api/account',{method:'POST',headers:{'Content-Type':'application/json','X-QueuePilot-Request':'1',Origin:'https://queuepilot.test'},body:JSON.stringify({action:'create',name:'Legacy workspace',sample:false})}));assert.equal(response.status,200);const org=(await response.json()).id;
  globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-email':'legacy@example.com'});
  response=await http.account.GET();assert.equal(response.status,200);const again=await response.json();assert.equal(again.user.id,first.user.id);assert.equal(again.organizations[0].id,org);
  response=await http.workspace.GET(new Request('https://queuepilot.test/api/workspace/'+org),{params:Promise.resolve({path:[org]})});assert.equal(response.status,200);
  globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-email':'other@example.com'});response=await http.account.GET();assert.equal(response.status,200);assert.notEqual((await response.json()).user.id,first.user.id);
  response=await http.workspace.GET(new Request('https://queuepilot.test/api/workspace/'+org),{params:Promise.resolve({path:[org]})});assert.equal(response.status,403);
  globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-id':'an-id-without-email'});assert.equal((await http.account.GET()).status,401);
 }finally{db.close();globalThis.__qpTestEnv.DB=undefined;globalThis.__qpTestHeaders=new Headers()}
});
const opsBundle=await build({entryPoints:['lib/server/operations.ts'],bundle:true,format:'esm',platform:'node',write:false});
const {Operations}=await import('data:text/javascript;base64,'+Buffer.from(opsBundle.outputFiles[0].text).toString('base64'));
const ops=(db,user=alice)=>new Operations(db,user);
test('calendar atomically rejects overlaps, accepts adjacent work, and supports cancellation',async()=>{const {db,oa,ob}=await setup();try{const o=ops(db),base={memberId:alice.id,ticketId:null,title:'Install switch',starts:'2026-09-08T09:00:00Z',ends:'2026-09-08T10:00:00Z',kind:'Ticket work',notes:'',cancelled:false};const saved=await o.scheduleSave(oa,base);await assert.rejects(o.scheduleSave(oa,{...base,title:'Overlap',starts:'2026-09-08T09:30:00Z',ends:'2026-09-08T10:30:00Z'}),/schedule_overlap/);await o.scheduleSave(oa,{...base,title:'Adjacent',starts:'2026-09-08T10:00:00Z',ends:'2026-09-08T11:00:00Z'});await o.scheduleSave(oa,{...base,cancelled:true,version:1},saved.id);await o.scheduleSave(oa,base);const events=(await o.schedule(oa,new URL('https://test/?from=2026-09-08T00:00:00Z&to=2026-09-09T00:00:00Z'))).events;assert.equal(events.length,2);await assert.rejects(o.schedule(ob,new URL('https://test/?from=2026-09-08T00:00:00Z&to=2026-09-09T00:00:00Z')),failStatus(403));await assert.rejects(o.scheduleSave(oa,{...base,memberId:bob.id}),failStatus(400))}finally{db.close()}});
test('time entries reject overlaps and enforce ownership; a stopped timer saves only once',async()=>{const {db,a,oa,ca,ba}=await setup();try{const o=ops(db),t=await o.createTicket(oa,{title:'Timed ticket',companyId:ca,boardId:ba}),base={ticketId:t.id,starts:'2026-01-01T09:00:00Z',ends:'2026-01-01T10:00:00Z',description:'Setup',billable:true};const saved=await o.timeSave(oa,base);await assert.rejects(o.timeSave(oa,{...base,starts:'2026-01-01T09:30:00Z'}),/time_overlap/);assert.equal((await o.time(oa,new URL('https://test'))).entries[0].minutes,60);await o.timer(oa,{action:'start',ticketId:t.id});await assert.rejects(o.timer(oa,{action:'start',ticketId:t.id}),/UNIQUE/);await o.timer(oa,{action:'stop',description:'Test timer',billable:false});await assert.rejects(o.timer(oa,{action:'stop',description:'Double stop',billable:false}),failStatus(409));assert.equal((await o.time(oa,new URL('https://test'))).entries.length,2);await a.invite(oa,{email:eve.email,role:'Engineer'});const engineer=ops(db,eve);await engineer.account();await engineer.acceptInvitation({invitationId:(await engineer.account()).invitations[0].id});await assert.rejects(engineer.timeSave(oa,{...base,version:1},saved.id),failStatus(403));await assert.rejects(engineer.scheduleSave(oa,{}),failStatus(403))}finally{db.close()}});
test('SLA snapshots require a public staff response and record resolution time',async()=>{const {db,oa,ca,ba}=await setup();try{const o=ops(db);await o.policySave(oa,{priority:'Critical',responseMinutes:15,resolutionMinutes:240,enabled:true,version:0});let t=await o.createTicket(oa,{title:'SLA ticket',companyId:ca,boardId:ba,priority:'Critical'});assert.equal(Date.parse(t.responseDue)-Date.parse(t.created),15*60000);assert.equal(Date.parse(t.resolutionDue)-Date.parse(t.created),240*60000);await o.addNote(oa,String(t.id),{body:'Internal investigation',version:t.version});t=await o.ticket(oa,t.id);assert.equal(t.responded,null);await o.reply(oa,t.id,{body:'We are investigating.'});t=await o.ticket(oa,t.id);assert.ok(t.responded);t=await o.updateTicket(oa,String(t.id),{status:'Resolved',version:t.version});assert.ok(t.resolved);await o.policySave(oa,{priority:'Critical',responseMinutes:30,resolutionMinutes:480,enabled:true,version:1});assert.equal((await o.ticket(oa,t.id)).responseDue,t.responseDue);await assert.rejects(o.policySave(oa,{priority:'Critical',responseMinutes:30,resolutionMinutes:480,enabled:true,version:1}),failStatus(409))}finally{db.close()}});
test('projects, tasks, and assets link only to the ticket company and preserve versions',async()=>{const {db,oa,ca,cb,ba}=await setup();try{const o=ops(db),t=await o.createTicket(oa,{title:'Related records',companyId:ca,boardId:ba});const project={name:'Core replacement',companyId:ca,description:'Replace switches',ownerId:alice.id,status:'Active',due:'2026-12-01',estimatedHours:20,visible:false};const p=await o.projectSave(oa,project);const task=await o.taskSave(oa,{projectId:p.id,title:'Stage switches',memberId:alice.id,due:'2026-11-01',done:false});await o.taskSave(oa,{projectId:p.id,title:'Stage switches',memberId:alice.id,due:'2026-11-01',done:true,version:1},task.id);assert.equal((await o.projects(oa)).projects[0].completedCount,1);const asset=await o.assetSave(oa,{companyId:ca,name:'Core 01',kind:'Switch',status:'Active',visible:false});await o.linksSave(oa,t.id,{projectId:p.id,assetId:asset.id});assert.equal((await o.links(oa,t.id)).links.assetId,asset.id);await assert.rejects(o.assetSave(oa,{companyId:cb,name:'Foreign',kind:'Switch',status:'Active',visible:false}),failStatus(400));const second=(await o.directory(oa,'companies',{name:'Other Alpha company'})).id;const p2=await o.projectSave(oa,{...project,name:'Other project',companyId:second});await assert.rejects(o.linksSave(oa,t.id,{projectId:p2.id,assetId:null}),failStatus(400));await assert.rejects(o.projectSave(oa,{...project,companyId:second,version:1},p.id),failStatus(409));await assert.rejects(o.updateTicket(oa,String(t.id),{companyId:second,version:t.version}),failStatus(409))}finally{db.close()}});
test('customer portal never returns internal notes, private equipment, audit or another company',async()=>{const {db,oa,ob,ca,ba}=await setup();try{const staff=ops(db),customer=ops(db,{id:'customer',name:'Customer',email:'customer@example.com'});const ticket=await staff.createTicket(oa,{title:'Visible request',description:'Public issue',companyId:ca,boardId:ba});await staff.addNote(oa,String(ticket.id),{body:'INTERNAL_SECRET',version:ticket.version});await staff.assetSave(oa,{name:'Private asset',companyId:ca,kind:'Server',status:'Active',visible:false});await staff.assetSave(oa,{name:'Shared asset',companyId:ca,kind:'Computer',status:'Active',visible:true,ip:'PRIVATE_IP',notes:'PRIVATE_NOTES'});await staff.projectSave(oa,{name:'Private project',companyId:ca,description:'PRIVATE_PROJECT',ownerId:null,status:'Planning',due:'',estimatedHours:0,visible:false});await assert.rejects(customer.portalData(oa,ca,new URL('https://test')),failStatus(403));await staff.grantSave(oa,{companyId:ca,email:'customer@example.com'});await customer.portalAccount();const publicData=JSON.stringify(await customer.portalData(oa,ca,new URL('https://test')));assert.ok(publicData.includes('Shared asset'));assert.ok(!/Private asset|PRIVATE_IP|PRIVATE_NOTES|PRIVATE_PROJECT/.test(publicData));const detail=JSON.stringify(await customer.portalTicket(oa,ca,ticket.id));assert.ok(!/INTERNAL_SECRET|activity|notes/.test(detail));await customer.reply(oa,ticket.id,{body:'Customer update'},ca);assert.equal((await staff.messages(oa,ticket.id)).messages[0].kind,'Customer');const created=await customer.portalCreate(oa,ca,{title:'Portal request',description:'Help please'});assert.ok(created.id);await assert.rejects(customer.workspace(oa),failStatus(403));await assert.rejects(customer.portalData(ob,ca,new URL('https://test')),failStatus(403));const grant=(await staff.grants(oa)).grants[0];await staff.grantRevoke(oa,grant.id);await assert.rejects(customer.portalTicket(oa,ca,ticket.id),failStatus(403))}finally{db.close()}});
test('event rules execute once, use first match, support dry runs, and notify assignees',async()=>{const {db,oa,ca,ba}=await setup();try{const o=ops(db),rule={name:'Critical triage',trigger:'Ticket created',priority:'Critical',boardId:ba,status:'',enabled:true,actions:{assigneeId:alice.id,note:'Review immediately'}};const r=await o.ruleSave(oa,rule);await o.ruleSave(oa,{...rule,name:'Second rule',actions:{note:'SHOULD_NOT_RUN'}});const t=await o.createTicket(oa,{title:'Urgent issue',companyId:ca,boardId:ba,priority:'Critical'});assert.equal(t.assigneeId,alice.id);assert.equal(t.notes.length,1);assert.equal(t.notes[0].body,'Review immediately');assert.ok(t.activity.some(a=>a.action==='Automation: Critical triage'));const before=t.version;assert.equal((await o.ruleTest(oa,r.id,{ticketId:t.id})).matches,true);assert.equal((await o.ticket(oa,t.id)).version,before);const notices=await o.notifications(oa);assert.ok(notices.notifications.some(n=>n.ticketId===t.id));await o.readNotification(oa,{id:notices.notifications[0].id});assert.equal((await o.notifications(oa)).unread,0);await o.updateTicket(oa,String(t.id),{description:'Updated details',version:t.version});assert.equal((await o.ticket(oa,t.id)).notes.length,1);await assert.rejects(o.ruleSave(oa,{...rule,actions:{assigneeId:bob.id}}),failStatus(400))}finally{db.close()}});
test('reports aggregate actual ticket and time data and isolate company filters',async()=>{const {db,oa,ca,ba}=await setup();try{const o=ops(db),t=await o.createTicket(oa,{title:'Report work',companyId:ca,boardId:ba});await o.timeSave(oa,{ticketId:t.id,starts:'2026-01-01T09:00:00Z',ends:'2026-01-01T10:30:00Z',description:'Install',billable:true});const date=new Date().toISOString().slice(0,10);let report=await o.reports(oa,new URL('https://test/?from=2026-01-01&to='+date));assert.equal(report.summary.created,1);assert.equal(report.time.minutes,90);assert.equal(report.byTechnician[0].minutes,90);report=await o.reports(oa,new URL('https://test/?from=2026-01-01&to='+date+'&company=other-company'));assert.equal(report.summary.created,0);assert.equal(report.time.minutes,0);await assert.rejects(o.reports(oa,new URL('https://test/?from=2026-12-31&to=2026-01-01')),failStatus(400))}finally{db.close()}});
test('attachment uploads and downloads enforce customer visibility and tenant access',async()=>{const {db,oa,ca,ba}=await setup();const objects=new Map();try{globalThis.__qpTestEnv.DB=db;globalThis.__qpTestEnv.BUCKET={async put(key,buffer){objects.set(key,new Uint8Array(buffer))},async get(key){const value=objects.get(key);return value?{body:new Blob([value]).stream()}:null},async delete(key){objects.delete(key)}};const staff=ops(db),t=await staff.createTicket(oa,{title:'File test',companyId:ca,boardId:ba});globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-id':alice.id,'oai-authenticated-user-email':alice.email});const ctx={params:Promise.resolve({path:[oa,'tickets',String(t.id),'files']})};const upload=async visibility=>{const form=new FormData();form.set('file',new File(['Safe attachment body'],'report.txt',{type:'text/plain'}));form.set('visibility',visibility);return http.workspace.POST(new Request('https://queuepilot.test/api/workspace/'+oa+'/tickets/'+t.id+'/files',{method:'POST',headers:{'X-QueuePilot-Request':'1'},body:form}),ctx)};let r=await upload('Internal');assert.equal(r.status,200);const internal=(await r.json()).id;r=await upload('Customer');assert.equal(r.status,200);const shared=(await r.json()).id;assert.equal(objects.size,2);r=await http.workspace.GET(new Request('https://queuepilot.test/files'),{params:Promise.resolve({path:[oa,'tickets',String(t.id),'files',shared]})});assert.equal(r.status,200);assert.equal(r.headers.get('content-type'),'application/octet-stream');assert.match(r.headers.get('content-disposition'),/^attachment/);assert.equal(await r.text(),'Safe attachment body');await staff.grantSave(oa,{companyId:ca,email:'files-customer@example.com'});const customer=ops(db,{id:'files-customer',email:'files-customer@example.com',name:'Files customer'});await customer.portalAccount();const fileModule=await build({entryPoints:['lib/server/files.ts'],bundle:true,format:'esm',platform:'node',write:false,plugins:[{name:'r2-runtime',setup(b){b.onResolve({filter:/^cloudflare:workers$/},()=>({path:'env',namespace:'r2'}));b.onLoad({filter:/.*/,namespace:'r2'},()=>({contents:'export const env=globalThis.__qpTestEnv',loader:'js'}));}}]});const {fileRequest}=await import('data:text/javascript;base64,'+Buffer.from(fileModule.outputFiles[0].text).toString('base64'));const list=await fileRequest(customer,new Request('https://test/files'),oa,t.id,undefined,ca);assert.deepEqual(list.files.map(f=>f.id),[shared]);await assert.rejects(fileRequest(customer,new Request('https://test/files'),oa,t.id,internal,ca),failStatus(404));assert.equal(await (await fileRequest(customer,new Request('https://test/files'),oa,t.id,shared,ca)).text(),'Safe attachment body');await assert.rejects(fileRequest(customer,new Request('https://test/files'),oa,t.id,shared,'another-company'),failStatus(403));}finally{db.close();globalThis.__qpTestEnv.DB=undefined;globalThis.__qpTestEnv.BUCKET=undefined;globalThis.__qpTestHeaders=new Headers()}});
const advancedBundle=await build({stdin:{contents:"export {Advanced,parseCSV} from './lib/server/advanced.ts';export {businessDeadline} from './lib/server/automation.ts'",resolveDir:process.cwd()},bundle:true,format:'esm',platform:'node',write:false});
