test('custom roles replace operational permissions and cannot elevate administration',async()=>{const {db,a,oa,ob,ca,ba}=await setup();try{const s=new Advanced(db,alice),v=new Advanced(db,eve);await v.account();await a.invite(oa,{email:eve.email,role:'Engineer'});await v.acceptInvitation({invitationId:(await v.account()).invitations[0].id});const role=await s.customRoleSave(oa,{name:'Asset specialist',capabilities:['assets:write']});await s.customRoleAssign(oa,{userId:eve.id,roleId:role.id});assert.equal((await v.context(oa)).roleName,'Asset specialist');await assert.rejects(v.createTicket(oa,{title:'Denied',companyId:ca,boardId:ba}),failStatus(403));await v.context(oa,'assets:write');await assert.rejects(s.customRoleSave(oa,{name:'Escalated',capabilities:['team:write']}),failStatus(400));await assert.rejects(v.customRoleSave(oa,{name:'No',capabilities:[]}),failStatus(403));await assert.rejects(s.customRoleAssign(oa,{userId:alice.id,roleId:role.id}),failStatus(403));await assert.rejects(s.customRoles(ob),failStatus(403));await a.role(oa,eve.id,{role:'Engineer'});await v.context(oa,'tickets:write');}finally{db.close()}});
test('CSV parser handles quoted commas and newlines; imports preview, reject errors, skip duplicates and isolate tenants',async()=>{const {db,oa,ob}=await setup();try{const s=new Advanced(db,alice);assert.deepEqual(parseCSV('name,notes\r\n"Acme, Inc","Line 1\nLine 2"'),[{name:'Acme, Inc',notes:'Line 1\nLine 2'}]);assert.throws(()=>parseCSV('name\n"unclosed'));let r=await s.importCSV(oa,{kind:'companies',csv:'name,email\nNew Corp,hello@example.com'});assert.equal(r.created,1);assert.equal((await s.workspace(oa)).companies.length,1);r=await s.importCSV(oa,{kind:'companies',csv:'name,email\nNew Corp,hello@example.com',apply:true});assert.equal(r.created,1);r=await s.importCSV(oa,{kind:'companies',csv:'name,email\nNew Corp,hello@example.com',apply:true});assert.equal(r.created,0);assert.equal(r.skipped,1);await assert.rejects(s.importCSV(oa,{kind:'contacts',csv:'name,company,email\nJane,Beta customer,jane@example.com',apply:true}),failStatus(400));await s.importCSV(oa,{kind:'contacts',csv:'name,company,email\nJane,New Corp,jane@example.com',apply:true});await s.importCSV(oa,{kind:'assets',csv:'name,company,serial\nLaptop,New Corp,ABC',apply:true});assert.equal((await s.assets(oa)).assets.length,1);await assert.rejects(s.importCSV(ob,{kind:'companies',csv:'name\nNo',apply:true}),failStatus(403));}finally{db.close()}});
test('child relations prevent cycles and tenant/company changes; merges preserve source audit and consolidate notes',async()=>{const {db,a,oa,ca,ba}=await setup();try{const s=new Advanced(db,alice),parent=await a.createTicket(oa,{title:'Parent',companyId:ca,boardId:ba}),child=await a.createTicket(oa,{title:'Child',companyId:ca,boardId:ba,parentId:parent.id});assert.equal((await s.relations(oa,parent.id)).relations.length,1);await assert.rejects(s.relationSave(oa,parent.id,{kind:'parent',targetId:child.id,version:parent.version}),failStatus(400));await s.relationSave(oa,child.id,{kind:'parent',targetId:null,version:child.version});const source=await s.addNote(oa,String(child.id),{body:'Keep this history',version:2});await s.relationSave(oa,child.id,{kind:'merge',targetId:parent.id,version:source.version,targetVersion:parent.version});const merged=await s.ticket(oa,parent.id);assert.ok(merged.notes.some(n=>n.body==='Keep this history'));assert.equal((await s.ticket(oa,child.id)).closed,1);assert.ok((await s.ticket(oa,child.id)).activity.some(a=>a.action==='Ticket merged'));await assert.rejects(s.updateTicket(oa,String(child.id),{status:'New',version:4}),failStatus(409));}finally{db.close()}});
test('recurring runs are idempotent, advance overdue schedules, and apply ticket automation',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Advanced(db,alice);await s.configSave(oa,'recurring',{name:'Weekly checks',title:'Check backups',description:'Verify restore',companyId:ca,boardId:ba,assigneeId:null,priority:'Normal',intervalDays:7,nextDue:'2020-01-01T09:00:00.000Z',enabled:true});assert.equal((await s.runRecurring(oa)).created,1);assert.equal((await s.runRecurring(oa)).created,0);assert.equal((await s.listTickets(oa,new URL('https://test/?view=all'))).total,1);}finally{db.close()}});
test('business SLA skips weekends and holidays while preserving exact working minutes',()=>{const cal={enabled:true,startHour:9,endHour:17,weekdays:[1,2,3,4,5],holidays:'2026-09-07'};assert.equal(businessDeadline('2026-09-04T16:30:00.000Z',60,cal),'2026-09-08T09:30:00.000Z');assert.equal(businessDeadline('2026-09-04T08:30:00.000Z',30,cal),'2026-09-04T09:30:00.000Z');});
test('project templates are transactional and reject stale application; metadata respects tenant membership',async()=>{const {db,oa,ob,ca,ba}=await setup();try{const s=new Advanced(db,alice),p=await s.projectSave(oa,{name:'Upgrade',companyId:ca,ownerId:null,status:'Planning',due:'',estimatedHours:5,visible:false}),t=await s.configSave(oa,'project-template',{name:'Network',tasks:'Discover\nInstall\nTest'});await s.applyProjectTemplate(oa,{projectId:p.id,templateId:t.id,version:1});await assert.rejects(s.applyProjectTemplate(oa,{projectId:p.id,templateId:t.id,version:1}),failStatus(409));assert.equal((await s.project(oa,p.id)).tasks.length,3);const ticket=await s.createTicket(oa,{title:'Details',companyId:ca,boardId:ba});await s.metadataSave(oa,ticket.id,{type:'Incident',tags:'network,urgent',customFields:{Rack:'A1'}});assert.equal((await s.metadata(oa,ticket.id)).customFields.Rack,'A1');await assert.rejects(s.metadata(ob,ticket.id),failStatus(403));}finally{db.close()}});
test('task dependencies block cycles and completion until prerequisites are done',async()=>{const {db,oa,ca}=await setup();try{const s=new Advanced(db,alice),project=await s.projectSave(oa,{name:'Dependency project',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:1,visible:false}),first=await s.taskSave(oa,{projectId:project.id,title:'Discover',memberId:null,due:'',done:false}),second=await s.taskSave(oa,{projectId:project.id,title:'Deploy',memberId:null,due:'',done:false});await s.dependencySave(oa,{taskId:second.id,dependencyId:first.id});await assert.rejects(s.dependencySave(oa,{taskId:first.id,dependencyId:second.id}),/dependency_cycle/);await assert.rejects(s.taskSave(oa,{projectId:project.id,title:'Deploy',memberId:null,due:'',done:true,version:1},second.id),/dependency_incomplete/);await s.taskSave(oa,{projectId:project.id,title:'Discover',memberId:null,due:'',done:true,version:1},first.id);await s.taskSave(oa,{projectId:project.id,title:'Deploy',memberId:null,due:'',done:true,version:1},second.id);assert.equal((await s.project(oa,project.id)).tasks.filter(t=>t.done).length,2);}finally{db.close()}});
test('report filters and notification preferences are applied to persisted data',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Advanced(db,alice);await s.prefs(oa,{assignment:false});const t=await s.createTicket(oa,{title:'Quiet assignment',companyId:ca,boardId:ba,assigneeId:alice.id});assert.equal((await s.notifications(oa)).unread,0);const day=new Date().toISOString().slice(0,10);const r=await s.reports(oa,new URL(`https://test/?from=${day}&to=${day}&board=${ba}&technician=alice`));assert.equal(r.summary.created,1);assert.equal((await s.reports(oa,new URL(`https://test/?from=${day}&to=${day}&technician=unknown`))).summary.created,0);const search=await s.search(oa,new URL('https://test/?q=Quiet'));assert.ok(search.results.some(r=>r.id===t.id));}finally{db.close()}});
