test('project financial plan uses cents, linked time and expense states; currency and versions cannot silently change',async()=>{const {db,oa,ob,ca,ba}=await setup();try{const s=new Delivery(db,alice),p=await s.projectSave(oa,{name:'Finance project',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:10,visible:true}),plan={budget:1000,laborRate:60,currency:'USD',startDate:'2026-09-07',notes:'Internal margin assumptions',version:0};await s.planSave(oa,p.id,plan);const t=await s.createTicket(oa,{title:'Install',companyId:ca,boardId:ba});await s.linksSave(oa,t.id,{projectId:p.id,assetId:null});await s.timeSave(oa,{ticketId:t.id,starts:'2020-01-01T10:00:00.000Z',ends:'2020-01-01T11:30:00.000Z',description:'Install',billable:true});const expense={projectId:p.id,description:'Switch',vendor:'Vendor',category:'Hardware',amount:120.25,date:'2026-09-07',status:'Paid',currency:'USD'};const e=await s.expenseSave(oa,expense);await s.expenseSave(oa,{...expense,description:'Planned travel',amount:30,status:'Planned'});let f=await s.projectFinance(oa,p.id);assert.equal(f.totals.laborCost,90);assert.equal(f.totals.actualExpenses,120.25);assert.equal(f.totals.plannedExpenses,30);assert.equal(f.totals.remaining,789.75);assert.equal(f.totals.hours,1.5);await assert.rejects(s.planSave(oa,p.id,{...plan,currency:'EUR',version:1}),failStatus(409));await assert.rejects(s.planSave(oa,p.id,{...plan,version:9}),failStatus(409));await assert.rejects(s.expenseSave(oa,{...expense,amount:1.234}));await assert.rejects(s.expenseSave(oa,{...expense,currency:'CAD'}),failStatus(409));await s.expenseSave(oa,{...expense,status:'Voided',version:1},e.id);assert.equal((await s.projectFinance(oa,p.id)).totals.actualExpenses,0);await assert.rejects(s.expenseSave(oa,{...expense,version:1},e.id),failStatus(409));await assert.rejects(s.projectFinance(ob,p.id),failStatus(403));}finally{db.close()}});
test('milestones enforce project and owner tenant boundaries and prevent moving between projects',async()=>{const {db,oa,ob,ca}=await setup();try{const s=new Delivery(db,alice),p=await s.projectSave(oa,{name:'Milestones',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false}),other=await s.projectSave(oa,{name:'Other project',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false}),value={projectId:p.id,title:'Acceptance',due:'2026-12-01',memberId:alice.id,completed:false,notes:'Customer sign-off'};const m=await s.milestoneSave(oa,value);await s.milestoneSave(oa,{...value,completed:true,version:1},m.id);assert.equal((await s.milestones(oa,p.id)).milestones[0].completed,1);await assert.rejects(s.milestoneSave(oa,{...value,version:1},m.id),failStatus(409));await assert.rejects(s.milestoneSave(oa,{...value,projectId:other.id,version:2},m.id),failStatus(409));await assert.rejects(s.milestoneSave(oa,{...value,memberId:bob.id}),failStatus(400));await assert.rejects(s.milestones(ob,p.id),failStatus(403));}finally{db.close()}});
test('locations and contact profiles enforce same-company links, safe contact moves and directory permissions',async()=>{const {db,a,oa,ob,ca}=await setup();try{const s=new Delivery(db,alice),other=(await s.directory(oa,'companies',{name:'Other customer'})).id,contact=(await s.directory(oa,'contacts',{name:'Jane',companyId:ca})).id,location=await s.locationSave(oa,{companyId:ca,name:'Main campus',address:'123 Main St',phone:'555-0100',notes:'Internal access code',active:true}),foreign=await s.locationSave(oa,{companyId:other,name:'Other campus',address:'',phone:'',notes:'',active:true}),profile={mobile:'555-0101',preferred:'Mobile',locationId:location.id,notes:'Internal contact context',version:0};await s.contactProfileSave(oa,contact,profile);assert.equal((await s.contactProfile(oa,contact)).profile.mobile,'555-0101');await assert.rejects(s.contactProfileSave(oa,contact,{...profile,locationId:foreign.id,version:1}),failStatus(400));await assert.rejects(s.directory(oa,'contacts',{name:'Jane',companyId:other,version:1},contact),/contact_location/);await s.contactProfileSave(oa,contact,{...profile,locationId:null,version:1});await s.directory(oa,'contacts',{name:'Jane',companyId:other,version:1},contact);await assert.rejects(s.contactProfile(ob,contact),failStatus(403));const viewer=new Delivery(db,eve);await viewer.account();await a.invite(oa,{email:eve.email,role:'Viewer'});await viewer.acceptInvitation({invitationId:(await viewer.account()).invitations[0].id});await viewer.contactProfile(oa,contact);await assert.rejects(viewer.locationSave(oa,{companyId:ca,name:'No',address:'',phone:'',notes:'',active:true}),failStatus(403));await assert.rejects(viewer.projectFinance(oa,'no-project'),failStatus(403));}finally{db.close()}});
const enterpriseBundle=await build({entryPoints:['lib/server/enterprise.ts'],bundle:true,format:'esm',platform:'node',write:false});
const {Enterprise}=await import('data:text/javascript;base64,'+Buffer.from(enterpriseBundle.outputFiles[0].text).toString('base64'));
test('board defaults distinguish omitted assignment and snapshot board SLA overrides',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Enterprise(db,alice),settings={defaultMemberId:alice.id,email:'help@example.com',labels:{Critical:'Urgent',High:'High',Normal:'Standard',Low:'Low'},targets:{Normal:{response:15,resolution:90}},version:0};await s.boardSettingsSave(oa,ba,settings);const t=await s.createTicket(oa,{title:'Default routing',companyId:ca,boardId:ba});assert.equal(t.assigneeId,alice.id);assert.equal(Date.parse(t.resolutionDue)-Date.parse(t.created),90*60000);assert.equal((await s.workspace(oa)).boards[0].priorityLabels.Normal,'Standard');assert.equal((await s.createTicket(oa,{title:'Explicit unassigned',companyId:ca,boardId:ba,assigneeId:null})).assigneeId,null);await assert.rejects(s.boardSettingsSave(oa,ba,{...settings,version:9}),failStatus(409));await assert.rejects(s.boardSettingsSave(oa,ba,{...settings,defaultMemberId:bob.id,version:1}),failStatus(400));}finally{db.close()}});
test('purchases preserve exact totals, enforce lifecycle and freeze approved drafts',async()=>{const {db,oa,ob,ca}=await setup();try{const s=new Enterprise(db,alice),p=await s.projectSave(oa,{name:'Purchases',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false}),value={projectId:p.id,vendor:'Supplier',reference:'PO-1',currency:'USD',items:[{description:'Cable',quantity:3,unitCost:10.15}],notes:''},r=await s.purchaseSave(oa,value);assert.equal((await s.purchasing(oa,p.id)).purchases[0].totalCents,3045);await assert.rejects(s.purchaseTransition(oa,r.id,{status:'Received',version:1}),failStatus(409));await s.purchaseTransition(oa,r.id,{status:'Approved',version:1});await assert.rejects(s.purchaseSave(oa,{...value,version:2},r.id),failStatus(409));await assert.rejects(s.purchaseTransition(oa,r.id,{status:'Ordered',version:1}),failStatus(409));await s.purchaseTransition(oa,r.id,{status:'Ordered',version:2});await s.purchaseTransition(oa,r.id,{status:'Received',version:3});assert.equal((await s.purchasing(oa,p.id)).purchases[0].status,'Received');assert.equal((await s.projectFinance(oa,p.id)).totals.actualExpenses,0);await assert.rejects(s.purchasing(ob,p.id),failStatus(403));}finally{db.close()}});
test('delivery templates atomically assign roles, dates, prerequisites and milestones',async()=>{const {db,oa,ca}=await setup();try{const s=new Enterprise(db,alice),p=await s.projectSave(oa,{name:'Rollout',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false}),value={name:'Deployment',tasks:[{title:'Prepare',role:'Engineer',days:0,dependsOn:null},{title:'Deploy',role:'Engineer',days:2,dependsOn:0}],milestones:[{title:'Acceptance',days:3}]},t=await s.templateSave(oa,value);await s.templateApply(oa,t.id,{projectId:p.id,version:1,start:'2026-09-07',owners:{Engineer:alice.id}});const tasks=(await s.project(oa,p.id)).tasks;assert.equal(tasks.length,2);assert.equal(tasks.find(t=>t.title==='Deploy').due,'2026-09-09');assert.equal(tasks[0].memberId,alice.id);assert.equal((await s.milestones(oa,p.id)).milestones[0].due,'2026-09-10');await assert.rejects(s.templateApply(oa,t.id,{projectId:p.id,version:1,start:'2026-09-07',owners:{}}),failStatus(409));assert.equal((await s.project(oa,p.id)).tasks.length,2);await assert.rejects(s.templateSave(oa,{...value,tasks:[{...value.tasks[0],dependsOn:0}]}));}finally{db.close()}});
test('contact equipment links reject different companies and protect contact moves',async()=>{const {db,oa,ca}=await setup();try{const s=new Enterprise(db,alice),other=(await s.directory(oa,'companies',{name:'Other'})).id,c=(await s.directory(oa,'contacts',{name:'Jane',companyId:ca})).id,a=await s.assetSave(oa,{name:'Laptop',companyId:ca,kind:'Computer',status:'Active',visible:false}),b=await s.assetSave(oa,{name:'Other laptop',companyId:other,kind:'Computer',status:'Active',visible:false});await s.linkAsset(oa,c,{assetId:a.id,remove:false});assert.equal((await s.linkedAssets(oa,c)).links[0].assetId,a.id);await assert.rejects(s.linkAsset(oa,c,{assetId:b.id,remove:false}),failStatus(400));await assert.rejects(s.directory(oa,'contacts',{name:'Jane',companyId:other,version:1},c),/contact_asset/);await s.linkAsset(oa,c,{assetId:a.id,remove:true});await s.directory(oa,'contacts',{name:'Jane',companyId:other,version:1},c);}finally{db.close()}});
test('automation creates linked tasks once, mentions respect preferences and scans deduplicate',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Enterprise(db,alice),p=await s.projectSave(oa,{name:'Follow-up',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false}),t=await s.createTicket(oa,{title:'Follow up',companyId:ca,boardId:ba,assigneeId:alice.id});await s.linksSave(oa,t.id,{projectId:p.id,assetId:null});await s.ruleSave(oa,{name:'Follow-up task',trigger:'Ticket updated',priority:'',boardId:'',status:'',enabled:true,actions:{taskTitle:'Review update',notifyUserId:alice.id}});await s.updateTicket(oa,String(t.id),{description:'Changed',version:t.version});assert.equal((await s.project(oa,p.id)).tasks.length,1);await assert.rejects(s.updateTicket(oa,String(t.id),{description:'Stale',version:t.version}),failStatus(409));assert.equal((await s.project(oa,p.id)).tasks.length,1);await s.prefs(oa,{mentions:false});await s.addNote(oa,String(t.id),{body:'Mention quiet',version:2,mentionIds:[alice.id]});assert.ok(!(await s.notifications(oa)).notifications.some(n=>n.title.startsWith('Mentioned')));await s.stmt("UPDATE tickets SET resolution_due='2020-01-01T00:00:00.000Z' WHERE org_id=? AND id=?",oa,t.id).run();assert.equal((await s.scanNotifications(oa)).created,1);assert.equal((await s.scanNotifications(oa)).checked,0);}finally{db.close()}});
test('company documents hide internal and private-project files from customers',async()=>{const {db,oa,ca}=await setup();const objects=new Map();try{globalThis.__qpTestEnv.BUCKET={async put(k,b){objects.set(k,new Uint8Array(b))},async get(k){return objects.has(k)?{body:new Blob([objects.get(k)]).stream()}:null},async delete(k){objects.delete(k)}};const bundle=await build({entryPoints:['lib/server/documents.ts'],bundle:true,format:'esm',platform:'node',write:false,plugins:[{name:'document-runtime',setup(b){b.onResolve({filter:/^cloudflare:workers$/},()=>({path:'env',namespace:'r2'}));b.onLoad({filter:/.*/,namespace:'r2'},()=>({contents:'export const env=globalThis.__qpTestEnv',loader:'js'}));}}]});const {documentRequest}=await import('data:text/javascript;base64,'+Buffer.from(bundle.outputFiles[0].text).toString('base64')),s=new Enterprise(db,alice),customer=new Enterprise(db,{id:'doc-customer',email:'doc@example.com',name:'Doc customer'}),pv={name:'Private rollout',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false},p=await s.projectSave(oa,pv);await s.grantSave(oa,{companyId:ca,email:'doc@example.com'});await customer.portalAccount();const upload=async(kind,rid,visibility)=>{const f=new FormData();f.set('file',new File(['Document body'],'guide.html'));f.set('visibility',visibility);return documentRequest(s,new Request('https://test/doc',{method:'POST',headers:{'X-QueuePilot-Request':'1'},body:f}),oa,kind,rid)};const internal=await upload('company',ca,'Internal'),shared=await upload('company',ca,'Customer'),project=await upload('project',p.id,'Customer'),get=()=>new Request('https://test/doc');assert.deepEqual((await documentRequest(customer,get(),oa,'company',ca,undefined,true)).files.map(f=>f.id),[shared.id]);await assert.rejects(documentRequest(customer,get(),oa,'company',ca,internal.id,true),failStatus(404));await assert.rejects(documentRequest(customer,get(),oa,'company',ca,project.id,true),failStatus(404));await s.projectSave(oa,{...pv,visible:true,version:1},p.id);assert.equal((await documentRequest(customer,get(),oa,'company',ca,undefined,true)).files.length,2);const download=await documentRequest(customer,get(),oa,'company',ca,shared.id,true);assert.equal(download.headers.get('Content-Type'),'application/octet-stream');assert.equal(await download.text(),'Document body');const other=(await s.directory(oa,'companies',{name:'Other doc company'})).id;await assert.rejects(s.projectSave(oa,{...pv,companyId:other,version:2},p.id),/document_company/);}finally{db.close();globalThis.__qpTestEnv.BUCKET=undefined}});
test('customer-response rules apply guarded ticket and project effects',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Enterprise(db,alice),c=new Enterprise(db,{id:'reply-customer',email:'reply@example.com',name:'Customer'}),t=await s.createTicket(oa,{title:'Awaiting reply',companyId:ca,boardId:ba}),p=await s.projectSave(oa,{name:'Replies',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:true});await s.linksSave(oa,t.id,{projectId:p.id,assetId:null});await s.grantSave(oa,{companyId:ca,email:'reply@example.com'});await c.portalAccount();await s.ruleSave(oa,{name:'Reply follow-up',trigger:'Customer responded',priority:'',boardId:'',status:'',enabled:true,actions:{priority:'High',taskTitle:'Review customer reply',note:'Customer replied',notifyUserId:alice.id}});await c.reply(oa,t.id,{body:'Ready to proceed'},ca);const updated=await s.ticket(oa,t.id);assert.equal(updated.priority,'High');assert.equal(updated.notes[0].body,'Customer replied');assert.equal((await s.project(oa,p.id)).tasks.length,1);assert.equal((await s.messages(oa,t.id)).messages[0].body,'Ready to proceed');}finally{db.close()}});
const completionBundle=await build({entryPoints:['lib/server/completion.ts'],bundle:true,format:'esm',platform:'node',write:false});
