test('invoice ledger enforces issue locks, payment limits, currency and tenant isolation',async()=>{const {db,oa,ob,ca}=await setup();try{const s=new Completion(db,alice),pv={name:'Invoice project',companyId:ca,ownerId:null,status:'Active',due:'',estimatedHours:0,visible:false},p=await s.projectSave(oa,pv),plan={budget:1000,laborRate:60,currency:'USD',startDate:'',notes:'',version:0};await s.planSave(oa,p.id,plan);const value={companyId:ca,projectId:p.id,reference:'INV-001',description:'Installation',amount:100.25,currency:'USD',issued:'2026-09-07',due:'2026-09-30'},i=await s.invoiceSave(oa,value);await s.invoiceAction(oa,i.id,{action:'issue',version:1});await assert.rejects(s.invoiceSave(oa,{...value,version:2},i.id),failStatus(409));await s.invoiceAction(oa,i.id,{action:'payment',amount:50,date:'2026-09-07',reference:'Wire',version:2});await assert.rejects(s.invoiceAction(oa,i.id,{action:'payment',amount:50,date:'2026-09-07',version:2}),failStatus(409));await assert.rejects(s.invoiceAction(oa,i.id,{action:'payment',amount:51,date:'2026-09-07',version:3}),failStatus(409));await assert.rejects(s.invoiceAction(oa,i.id,{action:'void',version:3}),failStatus(409));assert.equal((await s.billing(oa)).invoices[0].paid_cents,5000);const profit=(await s.profitability(oa)).projects[0];assert.equal(profit.invoiced,100.25);assert.equal(profit.paid,50);await assert.rejects(s.planSave(oa,p.id,{...plan,currency:'EUR',version:1}),/invoice_/);const other=(await s.directory(oa,'companies',{name:'Another customer'})).id;await assert.rejects(s.projectSave(oa,{...pv,companyId:other,version:1},p.id),/invoice_/);await assert.rejects(s.billing(ob),failStatus(403));}finally{db.close()}});
test('teams replace membership atomically and reject foreign users and stale edits',async()=>{const {db,oa}=await setup();try{const s=new Completion(db,alice),v={name:'Engineering',description:'Network delivery',members:[alice.id]},t=await s.teamSave(oa,v);await assert.rejects(s.teamSave(oa,{...v,members:[bob.id],version:1},t.id),failStatus(400));await s.teamSave(oa,{...v,members:[],version:1},t.id);await assert.rejects(s.teamSave(oa,{...v,version:1},t.id),failStatus(409));assert.equal((await s.teams(oa)).members.length,0);}finally{db.close()}});
test('read-only API keys are hashed, scope-bound, identity-bound and revocable',async()=>{const {db,oa}=await setup();try{const s=new Completion(db,alice),key=await s.keyCreate(oa,{name:'Reporting',scope:'tickets:read',days:1});assert.ok(key.token.startsWith('qp_'));assert.ok(!JSON.stringify(await s.keys(oa)).includes(key.token));const raw=await s.one('SELECT hash FROM api_keys WHERE org_id=?',oa);assert.notEqual(raw.hash,key.token);await s.verifyKey(oa,key.token,'tickets:read');await assert.rejects(s.verifyKey(oa,key.token,'events:read'),failStatus(403));await s.keyRevoke(oa,key.id);await assert.rejects(s.verifyKey(oa,key.token,'tickets:read'),failStatus(403));const second=await s.keyCreate(oa,{name:'Expired',scope:'events:read',days:1});await s.stmt("UPDATE api_keys SET expires='2020-01-01' WHERE org_id=? AND id=?",oa,second.id).run();await assert.rejects(s.verifyKey(oa,second.token,'events:read'),failStatus(403));}finally{db.close()}});
test('report definitions validate tenant filters and analytics use filtered logged hours',async()=>{const {db,oa,ob,ca,ba}=await setup();try{const s=new Completion(db,alice),d={name:'Monthly engineering',days:30,capacityHours:8,companyId:ca,boardId:ba,technicianId:alice.id},r=await s.recordSave(oa,'report-definition',d);assert.equal((await s.records(oa,'report-definition')).records[0].days,30);await assert.rejects(s.recordSave(oa,'report-definition',{...d,companyId:'foreign'}),failStatus(400));await assert.rejects(s.recordSave(oa,'connection',{name:'Slack',account:'ops',notes:'',version:1},r.id),failStatus(404));const t=await s.createTicket(oa,{title:'Analytics',companyId:ca,boardId:ba});await s.timeSave(oa,{ticketId:t.id,starts:'2026-09-07T10:00:00Z',ends:'2026-09-07T12:00:00Z',description:'Work',billable:true});const data=await s.analytics(oa,new URL('https://test/?from=2026-09-07&to=2026-09-07&capacity=8'));assert.equal(data.utilization[0].percent,25);assert.equal((await s.analytics(oa,new URL('https://test/?from=2026-09-07&to=2026-09-07&company=unknown'))).utilization.length,0);await assert.rejects(s.records(ob,'report-definition'),failStatus(403));}finally{db.close()}});
test('timed rules apply once per deadline without recursively triggering update rules',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Completion(db,alice),t=await s.createTicket(oa,{title:'Overdue outage',companyId:ca,boardId:ba});await s.ruleSave(oa,{name:'Overdue escalation',trigger:'Ticket overdue',priority:'',boardId:ba,status:'',enabled:true,actions:{status:'Escalated',note:'Review missed deadline'}});await s.ruleSave(oa,{name:'No recursion',trigger:'Ticket updated',priority:'',boardId:'',status:'',enabled:true,actions:{note:'SHOULD_NOT_RUN'}});await s.stmt("UPDATE tickets SET resolution_due='2020-01-01T00:00:00.000Z' WHERE org_id=? AND id=?",oa,t.id).run();assert.equal((await s.runTimedRules(oa)).applied,1);assert.equal((await s.runTimedRules(oa)).applied,0);const updated=await s.ticket(oa,t.id);assert.equal(updated.status,'Escalated');assert.equal(updated.notes.length,1);assert.equal(updated.notes[0].body,'Review missed deadline');}finally{db.close()}});
test('ticket briefs and resolved-history matching never cross organization boundaries',async()=>{const {db,oa,ob,ca,cb,ba,bb}=await setup();try{const s=new Completion(db,alice),other=new Completion(db,bob);const foreign=await other.createTicket(ob,{title:'Firewall foreign secret',companyId:cb,boardId:bb});await other.updateTicket(ob,String(foreign.id),{status:'Resolved',version:1});const first=await s.createTicket(oa,{title:'Firewall VPN failure',companyId:ca,boardId:ba});await s.updateTicket(oa,String(first.id),{status:'Resolved',version:1});const t=await s.createTicket(oa,{title:'Firewall connection',companyId:ca,boardId:ba});const brief=await s.assistance(oa,t.id);assert.equal(brief.similar.length,1);assert.equal(brief.similar[0].title,'Firewall VPN failure');assert.ok(!JSON.stringify(brief).includes('foreign secret'));}finally{db.close()}});
test('AI is disabled without organization setup and returns review-only provider drafts',async()=>{const {db,oa,ob,ca,ba}=await setup();const originalFetch=globalThis.fetch;try{globalThis.__qpTestEnv.DB=db;globalThis.__qpTestHeaders=new Headers({'oai-authenticated-user-id':alice.id,'oai-authenticated-user-email':alice.email});const s=new Completion(db,alice),t=await s.createTicket(oa,{title:'Draft response',companyId:ca,boardId:ba});const ctx={params:Promise.resolve({path:[oa,'ai']})};let r=await http.workspace.GET(new Request('https://test/ai'),ctx);assert.equal((await r.json()).available,false);const req=()=>new Request('https://test/ai',{method:'POST',headers:{'Content-Type':'application/json','X-QueuePilot-Request':'1'},body:JSON.stringify({kind:'rewrite',id:String(t.id),text:'We are checking the switch.'})});r=await http.workspace.POST(req(),ctx);assert.equal(r.status,503);Object.assign(globalThis.__qpTestEnv,{QUEUEPILOT_OPENAI_KEY:'dummy-test-key',QUEUEPILOT_AI_MODEL:'test-model',QUEUEPILOT_AI_ORGANIZATIONS:oa});let calls=0;globalThis.fetch=async(url,opts)=>{calls++;assert.equal(url,'https://api.openai.com/v1/responses');const b=JSON.parse(opts.body);assert.equal(b.store,false);assert.equal(b.input,JSON.stringify({draft:'We are checking the switch.'}));return Response.json({output:[{content:[{type:'output_text',text:'We are reviewing the switch and will share our findings.'}]}]})};r=await http.workspace.POST(req(),ctx);const draft=await r.json();assert.equal(r.status,200);assert.equal(draft.reviewRequired,true);assert.equal(calls,1);assert.equal((await s.messages(oa,t.id)).messages.length,0);r=await http.workspace.POST(req(),ctx);assert.equal(r.status,429);assert.equal(calls,1);}finally{globalThis.fetch=originalFetch;for(const k of ['DB','QUEUEPILOT_OPENAI_KEY','QUEUEPILOT_AI_MODEL','QUEUEPILOT_AI_ORGANIZATIONS'])delete globalThis.__qpTestEnv[k];globalThis.__qpTestHeaders=new Headers();db.close()}});
test('follow-up automation creates one open ticket with fresh SLA and no creation-rule recursion',async()=>{const {db,oa,ca,ba}=await setup();try{const s=new Completion(db,alice);await s.boardSettingsSave(oa,ba,{defaultMemberId:null,email:'',labels:{Critical:'Critical',High:'High',Normal:'Normal',Low:'Low'},targets:{Normal:{response:15,resolution:60}},version:0});await s.ruleSave(oa,{name:'Follow-up on creation',trigger:'Ticket created',priority:'',boardId:'',status:'',enabled:true,actions:{followupTitle:'Validate original request'}});const t=await s.createTicket(oa,{title:'New firewall',companyId:ca,boardId:ba});let page=await s.listTickets(oa,new URL('https://test/?view=all'));assert.equal(page.total,2);const follow=page.tickets.find(t=>t.title==='Validate original request');assert.equal(follow.closed,0);assert.equal(Date.parse(follow.resolutionDue)-Date.parse(follow.created),3600000);await s.ruleSave(oa,{name:'Closure check',trigger:'Ticket closed',priority:'',boardId:'',status:'',enabled:true,actions:{followupTitle:'Confirm acceptance'}});await s.updateTicket(oa,String(t.id),{status:'Closed',version:1});page=await s.listTickets(oa,new URL('https://test/?view=all'));assert.equal(page.total,3);assert.equal(page.tickets.find(t=>t.title==='Confirm acceptance').status,'New');await assert.rejects(s.updateTicket(oa,String(t.id),{status:'Closed',version:1}),failStatus(409));assert.equal((await s.listTickets(oa,new URL('https://test/?view=all'))).total,3);}finally{db.close()}});

test('ticket search handles formatted IDs, unordered words, contacts and combined filters without leaking tenants',async()=>{
 const {db,a,b,oa,ob,ca,cb,ba,bb}=await setup();try{
 const contact=(await a.directory(oa,'contacts',{name:'Jordan Reed',companyId:ca,email:'jordan@example.com'})).id;
 const t=await a.createTicket(oa,{title:'Wireless access point failure',description:'North campus',companyId:ca,contactId:contact,boardId:ba,priority:'High'});
 await b.createTicket(ob,{title:'Wireless access point failure',companyId:cb,boardId:bb});
 const list=p=>a.listTickets(oa,new URL('https://test/?'+new URLSearchParams({view:'all',...p})));
 for(const q of ['#'+t.id,'QP-'+t.id,'QV-'+t.id,'failure wireless','Jordan','jordan@example.com','North wireless'])assert.deepEqual((await list({q})).tickets.map(x=>x.id),[t.id],q);
 assert.equal((await list({q:'wireless',board:ba,company:ca,priority:'High'})).total,1);
 assert.equal((await list({q:'wireless',priority:'Low'})).total,0);
 assert.equal((await list({q:'wireless',company:cb})).total,0);
 assert.equal((await list({q:'wireless nonexistent'})).total,0);
 }finally{db.close()}
});

test('new service boards accept tickets with their own initial status and board filter',async()=>{
 const {db,a,oa,ca,ba}=await setup();try{
 const board=await a.directory(oa,'boards',{name:'Escalations',description:'Specialist queue',statuses:[{name:'Queued',closed:false},{name:'Done',closed:true}]});
 const ticket=await a.createTicket(oa,{title:'Specialist request',companyId:ca,boardId:board.id});
 assert.equal(ticket.boardId,board.id);assert.equal(ticket.status,'Queued');
 assert.deepEqual((await a.listTickets(oa,new URL('https://test/?view=all&board='+board.id))).tickets.map(t=>t.id),[ticket.id]);
 assert.equal((await a.listTickets(oa,new URL('https://test/?view=all&board='+ba))).total,0);
 }finally{db.close()}
});

test('exact status filters include custom and closed states while respecting board scope',async()=>{
 const {db,a,oa,ca,ba}=await setup();try{
 const board=await a.directory(oa,'boards',{name:'Approval',statuses:[{name:'Awaiting approval',closed:false},{name:'Finished',closed:true}]});
 const t=await a.createTicket(oa,{title:'Approval request',companyId:ca,boardId:board.id});
 const list=(status,boardId=board.id)=>a.listTickets(oa,new URL('https://test/?'+new URLSearchParams({view:'all',status,board:boardId})));
 assert.equal((await list('Awaiting approval')).total,1);
 assert.equal((await list('Awaiting')).total,0);
 assert.equal((await list('Awaiting approval',ba)).total,0);
 await a.updateTicket(oa,String(t.id),{status:'Finished',version:1});
 assert.equal((await list('Finished')).total,1);
 assert.equal((await list('Awaiting approval')).total,0);
 assert.equal((await list("' OR 1=1 --")).total,0);
 }finally{db.close()}
});
